import subprocess
import shlex
from pathlib import Path

# 运维场景：批量检查服务器磁盘使用率
# 配置文件格式：每行 "hostname:port"
CONFIG_PATH = Path("/etc/disk_check/hosts.conf")
ALLOWED_HOSTS = {"web-01", "web-02", "db-01", "cache-01"}

def load_hosts(config_path: Path) -> list[str]:
    """从配置文件加载主机列表，仅接受白名单内的主机名"""
    hosts = []
    try:
        with config_path.open("r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                host = line.split(":")[0].strip()
                # 白名单校验：非白名单主机直接丢弃
                if host in ALLOWED_HOSTS:
                    hosts.append(host)
                else:
                    print(f"[WARN] 忽略非白名单主机: {host}")
    except FileNotFoundError:
        print(f"[ERROR] 配置文件不存在: {config_path}")
    return hosts

def check_disk(host: str) -> None:
    """通过 SSH 远程执行 df 命令，使用列表参数避免注入"""
    # 安全关键点：使用列表形式传递参数，shell=False（默认）
    # 即使 host 来自外部输入，也被当作单个参数传给 ssh，不会触发 shell 解析
    cmd = ["ssh", f"{host}", "df -h /"]
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            timeout=30,
            check=False  # 不抛异常，由调用方处理返回码
        )
        print(f"=== {host} ===")
        print(result.stdout if result.returncode == 0 else result.stderr)
    except subprocess.TimeoutExpired:
        print(f"[ERROR] 主机 {host} 连接超时")

def main() -> None:
    hosts = load_hosts(CONFIG_PATH)
    if not hosts:
        print("[ERROR] 未找到有效主机，退出")
        return

    for host in hosts:
        # 即使 host 被篡改（如 "web-01; rm -rf /"），
        # 列表参数会将其作为 ssh 的用户名参数，而不是 shell 命令
        check_disk(host)

if __name__ == "__main__":
    main()

