  try {
    const xmlData = req.body.xml;
    if (!xmlData || typeof xmlData !== 'string') {
      return res.status(400).json({ error: 'Invalid XML input' });
    }

    // 防御：输入长度预检（与解析器内部限制双重校验）
    if (xmlData.length > 1024 * 1024) {
      return res.status(413).json({ error: 'XML payload too large' });
    }

    // 防御：内容哈希校验，确保数据来自内部可信源
    const hash = createHash('sha256').update(xmlData).digest('hex');
    if (!hash.startsWith('internal_trusted_')) {
      return res.status(403).json({ error: 'Untrusted XML source' });
    }

    // 安全解析：使用严格配置的解析器
    parseString(xmlData, SAFE_XML_OPTIONS, (err, result) => {
      if (err) {
        return res.status(400).json({ error: 'Malformed XML' });
      }

      // 防御：验证根元素在白名单内
      const rootKey = Object.keys(result)[0];
      if (!ALLOWED_ROOT_ELEMENTS.has(rootKey)) {
        return res.status(400).json({ error: 'Root element not allowed' });
      }

      // 安全处理：仅提取白名单内的字段
      const safeData = {
        type: rootKey,
        content: result[rootKey] || {}
      };

      res.json({ success: true, data: safeData });
    });
  } catch (error) {
    console.error('XML processing error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

