import (
	"context"
	"fmt"
	"net/http"
	"os/exec"
	"strings"
	"time"
)

// GatewayConfig holds the whitelist of allowed commands for the API gateway
var GatewayConfig = struct {
	AllowedCommands map[string]bool
	Timeout         time.Duration
}{
	AllowedCommands: map[string]bool{
		"ping":   true,
		"traceroute": true,
		"nslookup": true,
	},
	Timeout: 5 * time.Second,
}

// NetworkDiagnosticHandler processes diagnostic requests from authenticated users
func NetworkDiagnosticHandler(w http.ResponseWriter, r *http.Request) {
	// Only allow GET requests with query parameters
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// Extract command and target from query params
	cmdName := r.URL.Query().Get("cmd")
	target := r.URL.Query().Get("target")

	// Validate: command must be in whitelist
	if !GatewayConfig.AllowedCommands[cmdName] {
		http.Error(w, "command not permitted", http.StatusForbidden)
		return
	}

	// Validate: target must be a valid hostname (alphanumeric, hyphen, dot only)
	if !isValidHostname(target) {
		http.Error(w, "invalid target", http.StatusBadRequest)
		return
	}

	// Build command with explicit argument list (no shell interpretation)
	ctx, cancel := context.WithTimeout(r.Context(), GatewayConfig.Timeout)
	defer cancel()

	// Safe: exec.Command with separate args, shell=False equivalent in Go
	cmd := exec.CommandContext(ctx, cmdName, target)

	// Capture output
	output, err := cmd.CombinedOutput()
	if err != nil {
		// Check if timeout occurred
		if ctx.Err() == context.DeadlineExceeded {
			http.Error(w, "command timed out", http.StatusGatewayTimeout)
			return
		}
		http.Error(w, fmt.Sprintf("execution failed: %v", err), http.StatusInternalServerError)
		return
	}

	// Return output with proper content type
	w.Header().Set("Content-Type", "text/plain")
	w.Write(output)
}

// isValidHostname validates hostname format: letters, digits, hyphens, dots only
func isValidHostname(s string) bool {
	if len(s) == 0 || len(s) > 253 {
		return false
	}
	for _, r := range s {
		if !(r >= 'a' && r <= 'z') &&
			!(r >= 'A' && r <= 'Z') &&
			!(r >= '0' && r <= '9') &&
			r != '-' && r != '.' {
			return false
		}
	}
	return true
}

func main() {
	http.HandleFunc("/diagnostic", NetworkDiagnosticHandler)
	http.ListenAndServe(":8080", nil)
}

