// deploy.js - CI/CD 自动化部署脚本
const { execFile } = require('child_process');
const path = require('path');

// 定义允许部署的环境白名单
const ALLOWED_ENVIRONMENTS = ['staging', 'production'];
const ALLOWED_BRANCHES = ['main', 'release/*'];

// 校验环境名称，防止路径穿越和命令注入
function isValidEnvironment(env) {
  return ALLOWED_ENVIRONMENTS.includes(env);
}

// 校验分支名称，支持 release/ 前缀，但拒绝包含 shell 元字符
function isValidBranch(branch) {
  if (typeof branch !== 'string' || branch.length > 100) return false;
  // 只允许字母数字、连字符、下划线和 release/ 前缀
  if (!/^[a-zA-Z0-9_\-]+$/.test(branch) && !/^release\/[a-zA-Z0-9_\-]+$/.test(branch)) {
    return false;
  }
  return true;
}

// 执行部署命令，使用 execFile 避免 shell 解释
function deploy(environment, branch) {
  // 防御：白名单校验环境
  if (!isValidEnvironment(environment)) {
    console.error(`Invalid environment: ${environment}`);
    return { success: false, error: 'INVALID_ENV' };
  }

  // 防御：白名单校验分支
  if (!isValidBranch(branch)) {
    console.error(`Invalid branch: ${branch}`);
    return { success: false, error: 'INVALID_BRANCH' };
  }

  // 构建部署脚本路径（固定脚本，不接受用户输入）
  const scriptPath = path.join(__dirname, 'scripts', 'deploy.sh');

  // 防御：使用 execFile 数组参数，shell=false（默认），命令不会被 shell 解释
  return new Promise((resolve) => {
    execFile(
      '/bin/bash',
      [scriptPath, environment, branch],
      { timeout: 30000, maxBuffer: 1024 * 1024 },
      (error, stdout, stderr) => {
        if (error) {
          console.error(`Deploy failed: ${error.message}`);
          resolve({ success: false, error: error.message });
        } else {
          console.log(`Deploy output: ${stdout}`);
          resolve({ success: true, output: stdout });
        }
      }
    );
  });
}

// 示例调用
deploy('staging', 'main');
